7. What is the output? Why is the field access surprising?
class Base {
    int value = 100;
    int getValue() { return value; }
}
class Derived extends Base {
    int value = 200;
    @Override
    int getValue() { return value; }
}
public class Test {
    public static void main(String[] args) {
        Base obj = new Derived();
        System.out.println(obj.value);      // Line 1
        System.out.println(obj.getValue()); // Line 2
    }
}

8. Identify all uses of 'this' and 'super' in this code and explain each:
class Vehicle {
    protected String brand;
    protected int speed;
    Vehicle(String brand, int speed) { this.brand = brand; this.speed = speed; }
    public String info() { return brand + "@" + speed; }
}
class ElectricCar extends Vehicle {
    private int batteryKWh;
    ElectricCar(String brand, int speed, int batteryKWh) {
        super(brand, speed);
        this.batteryKWh = batteryKWh;
    }
    @Override
    public String info() { return super.info() + "+" + batteryKWh + "kWh"; }
    public ElectricCar setBattery(int kWh) { this.batteryKWh = kWh; return this; }
}
